type result struct{ v int; err error }
ch := make(chan result, 1)          // buffered once: the pending value
ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
defer cancel()
go func() {
    v, err := compute(ctx)
    ch <- result{v, err}            // resolve (send) exactly once
}()

select {
case r := <-ch:                     // read end (await)
    return use(r.v), r.err
case <-ctx.Done():                  // deadline or cancellation wins
    return 0, ctx.Err()
}
